class Solution {
public:
    int subarraysDivByK(vector<int>& nums, int k) {
        vector<int> counts(k, 0);
        counts[0] = 1;
        int prefix = 0;
        int ans = 0;
        for (int x : nums) {
            prefix = ((prefix + x) % k + k) % k;
            ans += counts[prefix];
            counts[prefix]++;
        }
        return ans;
    }
};

